import json
from datetime import date
from types import SimpleNamespace as NS
from ta.models import Claim, FactRef, SourceRef
from ta.verify.quotes import match_quote_text
payload = json.dumps({"weights": {"MSFT": 0.05}, "notes": "AAPL dropped by risk caps"})
class ToolGateway:  # boundary stand-in for the tool gateway: returns one stored tool output and runs the real quote matcher
    ctx = NS(use_decisions=False)
    def call(self, agent, tool, args):
        if tool == "verify.reopen_source":
            return NS(output={"payload_text": payload, "hash_match": True})
        return NS(output=match_quote_text(args["quote"], args["text"]))
